<?php

namespace Tests\Unit\Libraries;

use App\Libraries\VoiceNoteUploader;
use Config\CbsRadio;
use PHPUnit\Framework\Attributes\DataProvider;
use ReflectionMethod;
use Tests\Support\Libraries\AudioFixtures;
use Tests\Support\TestCase\UnitTestCase;

/**
 * VoiceNoteUploader against real audio, made the way real devices make it (tests/_support/Audio, regenerated by
 * scripts/make-test-audio.sh). The container, not the file name, decides what PHP's file-type detection reports,
 * and audio-only WebM and MP4 are reported as *video* types, which is exactly the thing a synthetic test file hides.
 *
 * Tests that need to open the file (true length, "this is really a video") need ffprobe, which ships with ffmpeg,
 * and are skipped, loudly, where it is not installed. CI installs it.
 *
 * @internal
 */
final class VoiceNoteUploaderTest extends UnitTestCase
{
    private const STORE_SUBPATH = 'voice-notes-unit-test';

    protected function tearDown(): void
    {
        $this->removeDirectory(WRITEPATH . self::STORE_SUBPATH);
        AudioFixtures::cleanUp();

        parent::tearDown();
    }

    // ------------------------------------------------------------------ helpers

    /**
     * @param array<string, mixed> $config properties to set on the CbsRadio config
     */
    private function uploader(array $config = [], bool $verifyWithFfprobe = true): VoiceNoteUploader
    {
        $cbs = new CbsRadio();

        $cbs->voiceNoteVerifyWithFfprobe = $verifyWithFfprobe;
        $cbs->voiceNoteUploadSubpath     = self::STORE_SUBPATH;

        foreach ($config as $property => $value) {
            $cbs->{$property} = $value;
        }

        return new VoiceNoteUploader($cbs);
    }

    private function requireFfprobe(): void
    {
        if (trim((string) shell_exec('command -v ffprobe 2>/dev/null')) === '') {
            $this->markTestSkipped('ffprobe is not installed (it comes with ffmpeg), so the file cannot be opened to measure it.');
        }
    }

    private function removeDirectory(string $path): void
    {
        if (! is_dir($path)) {
            return;
        }

        foreach (scandir($path) ?: [] as $entry) {
            if ($entry !== '.' && $entry !== '..') {
                is_dir("{$path}/{$entry}") ? $this->removeDirectory("{$path}/{$entry}") : unlink("{$path}/{$entry}");
            }
        }

        rmdir($path);
    }

    // ------------------------------------------------------------------ the formats real devices produce

    /**
     * @return array<string, array{0: string, 1: string, 2: string}> fixture, what PHP reports for it, the device
     */
    public static function deviceFormats(): array
    {
        return [
            'Chrome, Edge, Android (WebM)'     => ['chrome-recording.webm', 'video/webm', 'voice-note.webm'],
            'Firefox (Ogg)'                    => ['firefox-recording.ogg', 'audio/ogg', 'voice-note.ogg'],
            'WhatsApp voice note (Opus)'       => ['whatsapp-voice.opus', 'audio/ogg', 'voice.opus'],
            'phone voice memo (M4A)'           => ['voice-memo.m4a', 'audio/x-m4a', 'memo.m4a'],
            'Safari and iPhone (MP4 as M4A)'   => ['safari-recording.m4a', 'video/mp4', 'voice-note.m4a'],
            'MP3'                              => ['recording.mp3', 'audio/mpeg', 'recording.mp3'],
            'WAV'                              => ['recording.wav', 'audio/x-wav', 'recording.wav'],
            'AAC'                              => ['recording.aac', 'audio/x-hx-aac-adts', 'recording.aac'],
        ];
    }

    #[DataProvider('deviceFormats')]
    public function testEveryDeviceFormatIsAcceptedAndItsTrueLengthMeasured(string $fixture, string $detectedAs, string $clientName): void
    {
        $this->requireFfprobe();

        $upload = AudioFixtures::upload($fixture, $clientName);

        $this->assertSame($detectedAs, $upload->getMimeType(), 'PHP now reports a different type for this file; the allow-list may need to follow.');

        $result = $this->uploader()->validate($upload, null);

        $this->assertTrue($result['valid'], $result['message']);
        $this->assertTrue($result['verified'], 'The length should have been measured from the file.');
        $this->assertEqualsWithDelta(6, $result['duration'], 1);
    }

    #[DataProvider('deviceFormats')]
    public function testEveryDeviceFormatIsAcceptedWithoutFfprobeToo(string $fixture, string $detectedAs, string $clientName): void
    {
        $result = $this->uploader(verifyWithFfprobe: false)->validate(AudioFixtures::upload($fixture, $clientName), 6);

        $this->assertTrue($result['valid'], $result['message']);
        $this->assertFalse($result['verified']);
        $this->assertSame(6, $result['duration'], 'Without ffprobe the browser\'s reported length is all there is.');
    }

    public function testAudioOnlyWebmAndMp4AreAllowedEvenThoughPhpCallsThemVideo(): void
    {
        // The regression this guards: the allow-list once held only audio/* types, so every Chrome recording was refused.
        $allowed = (new CbsRadio())->voiceNoteAllowedMimeTypes;

        $this->assertContains('video/webm', $allowed);
        $this->assertContains('video/mp4', $allowed);
        $this->assertContains('audio/x-m4a', $allowed);
        $this->assertContains('audio/x-hx-aac-adts', $allowed);
    }

    public function testTheFileExtensionIsMatchedIgnoringCase(): void
    {
        $result = $this->uploader(verifyWithFfprobe: false)->validate(AudioFixtures::upload('recording.mp3', 'RECORDING.MP3'), 6);

        $this->assertTrue($result['valid'], $result['message']);
    }

    // ------------------------------------------------------------------ what is not a voice note

    public function testATextFileIsRefused(): void
    {
        $result = $this->uploader(verifyWithFfprobe: false)->validate(AudioFixtures::upload('not-audio.txt', 'note.txt'), 6);

        $this->assertFalse($result['valid']);
        $this->assertStringContainsString("isn't a type of audio we can use", $result['message']);
    }

    public function testATextFileWithAnAudioNameIsStillRefused(): void
    {
        $result = $this->uploader(verifyWithFfprobe: false)->validate(AudioFixtures::upload('not-audio.txt', 'lovely-voice.mp3', 'audio/mpeg'), 6);

        $this->assertFalse($result['valid'], 'The name and the type the browser claims must not decide; the contents do.');
        $this->assertStringContainsString("isn't a type of audio we can use", $result['message']);
    }

    public function testRandomBytesAreRefused(): void
    {
        $result = $this->uploader(verifyWithFfprobe: false)->validate(AudioFixtures::upload('random-bytes.bin', 'voice.webm', 'audio/webm'), 6);

        $this->assertFalse($result['valid']);
    }

    #[DataProvider('dangerousNames')]
    public function testRealAudioUnderADangerousNameIsRefused(string $clientName): void
    {
        $result = $this->uploader(verifyWithFfprobe: false)->validate(AudioFixtures::upload('chrome-recording.webm', $clientName), 6);

        $this->assertFalse($result['valid']);
        $this->assertStringContainsString("file name doesn't look like an audio recording", $result['message']);
    }

    /**
     * @return array<string, array{0: string}>
     */
    public static function dangerousNames(): array
    {
        return [
            'a php file'        => ['voice.php'],
            'a double extension' => ['voice.webm.php'],
            'an executable'     => ['voice.exe'],
            'an mp4 video name' => ['clip.mp4'],
            'no extension'      => ['voice'],
        ];
    }

    public function testARealVideoWithASoundTrackIsRefusedWhenTheFileCanBeOpened(): void
    {
        $this->requireFfprobe();

        $result = $this->uploader()->validate(AudioFixtures::upload('video-with-sound.m4a', 'voice.m4a'), null);

        $this->assertFalse($result['valid']);
        $this->assertStringContainsString('looks like a video', $result['message']);
    }

    public function testWithoutFfprobeARealVideoIsNotCaughtAndThatIsADocumentedLimit(): void
    {
        // Pinned so the limit is explicit: without ffprobe, type, extension, size and the browser's own length are
        // all that can be checked, and a video in an MP4 container passes them. Moderators hear every note anyway.
        $result = $this->uploader(verifyWithFfprobe: false)->validate(AudioFixtures::upload('video-with-sound.m4a', 'voice.m4a'), 6);

        $this->assertTrue($result['valid']);
    }

    public function testATruncatedFileIsRefusedWhenTheFileCanBeOpened(): void
    {
        $this->requireFfprobe();

        $result = $this->uploader()->validate(AudioFixtures::upload('truncated.mp3', 'voice.mp3'), 6);

        $this->assertFalse($result['valid']);
        $this->assertNotSame('', $result['message']);
    }

    // ------------------------------------------------------------------ length

    public function testTheLengthIsMeasuredFromTheFileNotTakenFromTheBrowser(): void
    {
        $this->requireFfprobe();

        $liar = $this->uploader()->validate(AudioFixtures::upload('chrome-recording.webm', 'voice.webm'), 100);

        $this->assertTrue($liar['valid'], 'A 6-second note claiming 100 seconds is a 6-second note.');
        $this->assertSame(6, $liar['duration']);
        $this->assertTrue($liar['verified']);

        $understated = $this->uploader()->validate(AudioFixtures::upload('too-long-40s.webm', 'voice.webm'), 10);

        $this->assertFalse($understated['valid'], 'A 40-second note claiming 10 seconds is still 40 seconds.');
    }

    public function testATooLongNoteIsRefusedWithBothNumbers(): void
    {
        $this->requireFfprobe();

        $result = $this->uploader()->validate(AudioFixtures::upload('too-long-40s.webm', 'voice.webm'), null);

        $this->assertFalse($result['valid']);
        $this->assertSame('Your voice note is 40 seconds long. The longest allowed is 30 seconds.', $result['message']);
    }

    public function testATooShortNoteIsRefusedWithBothNumbers(): void
    {
        $this->requireFfprobe();

        $result = $this->uploader()->validate(AudioFixtures::upload('too-short-2s.webm', 'voice.webm'), null);

        $this->assertFalse($result['valid']);
        $this->assertSame('Your voice note is 2 seconds long. It needs to be at least 5 seconds.', $result['message']);
    }

    public function testTheLimitsComeFromTheConfiguration(): void
    {
        $this->requireFfprobe();

        $result = $this->uploader(['voiceNoteMaxSeconds' => 45])->validate(AudioFixtures::upload('too-long-40s.webm', 'voice.webm'), null);

        $this->assertTrue($result['valid'], 'Raising the maximum to 45 seconds should let a 40-second note through.');
        $this->assertSame(40, $result['duration']);
    }

    public function testAFractionOfASecondOutsideTheLimitsIsForgiven(): void
    {
        $this->requireFfprobe();

        // The recorder's clock and the finished file can differ by a little, so 6 seconds against a minimum of 6
        // or a maximum of 6 must pass, but a whole second out must not.
        $this->assertTrue($this->uploader(['voiceNoteMinSeconds' => 6])->validate(AudioFixtures::upload('chrome-recording.webm', 'a.webm'), null)['valid']);
        $this->assertTrue($this->uploader(['voiceNoteMaxSeconds' => 6])->validate(AudioFixtures::upload('chrome-recording.webm', 'a.webm'), null)['valid']);

        $tooShort = $this->uploader(['voiceNoteMinSeconds' => 7])->validate(AudioFixtures::upload('chrome-recording.webm', 'a.webm'), null);
        $this->assertFalse($tooShort['valid']);
        $this->assertSame('Your voice note is 6 seconds long. It needs to be at least 7 seconds.', $tooShort['message']);

        $tooLong = $this->uploader(['voiceNoteMaxSeconds' => 5])->validate(AudioFixtures::upload('chrome-recording.webm', 'a.webm'), null);
        $this->assertFalse($tooLong['valid']);
        $this->assertSame('Your voice note is 6 seconds long. The longest allowed is 5 seconds.', $tooLong['message']);
    }

    // ------------------------------------------------------------------ length without ffprobe: the browser's word is all there is

    #[DataProvider('claimedLengths')]
    public function testWithoutFfprobeTheBrowsersReportedLengthIsChecked(?int $claimed, bool $valid, ?string $message): void
    {
        $result = $this->uploader(verifyWithFfprobe: false)->validate(AudioFixtures::upload('chrome-recording.webm', 'voice.webm'), $claimed);

        $this->assertSame($valid, $result['valid']);

        if ($message !== null) {
            $this->assertSame($message, $result['message']);
        }
    }

    /**
     * @return array<string, array{0: int|null, 1: bool, 2: string|null}>
     */
    public static function claimedLengths(): array
    {
        return [
            'inside the limits'              => [6, true, null],
            'no length reported'             => [null, true, null],
            'exactly the minimum'            => [5, true, null],
            'exactly the maximum'            => [30, true, null],
            'one second too long'            => [31, false, 'Your voice note is 31 seconds long. The longest allowed is 30 seconds.'],
            'far too long'                   => [100, false, 'Your voice note is 100 seconds long. The longest allowed is 30 seconds.'],
            'too short'                      => [2, false, 'Your voice note is 2 seconds long. It needs to be at least 5 seconds.'],
            'one second is singular'         => [1, false, 'Your voice note is 1 second long. It needs to be at least 5 seconds.'],
            'zero seconds'                   => [0, false, 'Your voice note is 0 seconds long. It needs to be at least 5 seconds.'],
        ];
    }

    public function testWithoutAReportedLengthTheStoredLengthIsUnknown(): void
    {
        $result = $this->uploader(verifyWithFfprobe: false)->validate(AudioFixtures::upload('chrome-recording.webm', 'voice.webm'), null);

        $this->assertTrue($result['valid']);
        $this->assertNull($result['duration']);
    }

    // ------------------------------------------------------------------ ffprobe availability

    public function testAMissingFfprobeFallsBackToTheBrowsersLengthAndRecoversWhenFound(): void
    {
        $this->requireFfprobe();

        $missing = $this->uploader(['voiceNoteFfprobePath' => '/nonexistent/ffprobe'])
            ->validate(AudioFixtures::upload('chrome-recording.webm', 'a.webm'), 6);

        $this->assertTrue($missing['valid']);
        $this->assertFalse($missing['verified'], 'Nothing could be measured, so nothing is claimed to be verified.');

        // The answer is remembered per path, not per process: asking about the real ffprobe afterwards must work.
        $found = $this->uploader()->validate(AudioFixtures::upload('chrome-recording.webm', 'a.webm'), 6);

        $this->assertTrue($found['verified']);
    }

    // ------------------------------------------------------------------ size

    public function testAFileOverTheSizeLimitIsRefusedWithBothSizes(): void
    {
        $result = $this->uploader(['voiceNoteMaxSizeKB' => 10], false)->validate(AudioFixtures::upload('recording.wav', 'voice.wav'), 6);

        $this->assertFalse($result['valid']);
        $this->assertSame('Your voice note is 47 KB. The largest allowed is 10 KB. Try a shorter recording.', $result['message']);
    }

    #[DataProvider('sizes')]
    public function testSizesAreDescribedInPlainUnits(float $kb, string $expected): void
    {
        $method = new ReflectionMethod(VoiceNoteUploader::class, 'describeSize');

        $this->assertSame($expected, $method->invoke($this->uploader(), $kb));
    }

    /**
     * @return array<string, array{0: float, 1: string}>
     */
    public static function sizes(): array
    {
        return [
            'small'              => [128, '128 KB'],
            'just under a megabyte' => [1000, '1000 KB'],
            'exactly one MB'     => [1024, '1 MB'],
            'one and a half MB'  => [1536, '1.5 MB'],
            'two MB'             => [2048, '2 MB'],
        ];
    }

    // ------------------------------------------------------------------ the messages follow the configuration

    public function testTheListOfAcceptableFormatsComesFromTheConfiguration(): void
    {
        $uploader = $this->uploader(['voiceNoteAllowedExtensions' => ['mp3', 'wav']], false);

        $wrongType = $uploader->validate(AudioFixtures::upload('not-audio.txt', 'a.txt'), 6);
        $this->assertStringContainsString('choose an MP3 or WAV file.', $wrongType['message']);

        $wrongName = $uploader->validate(AudioFixtures::upload('chrome-recording.webm', 'a.webm'), 6);
        $this->assertStringContainsString('Choose an MP3 or WAV file.', $wrongName['message']);
    }

    public function testTheDefaultListNamesEveryAcceptedFormat(): void
    {
        $result = $this->uploader(verifyWithFfprobe: false)->validate(AudioFixtures::upload('not-audio.txt', 'a.txt'), 6);

        $this->assertStringContainsString('MP3, M4A, WAV, OGG, OPUS, WEBM or AAC', $result['message']);
    }

    // ------------------------------------------------------------------ uploads PHP itself refused

    #[DataProvider('phpUploadErrors')]
    public function testAnUploadPhpRefusedIsExplained(int $error, string $expected): void
    {
        $result = $this->uploader()->validate(AudioFixtures::failedUpload($error), 6);

        $this->assertFalse($result['valid']);
        $this->assertStringContainsString($expected, $result['message']);
    }

    /**
     * @return array<string, array{0: int, 1: string}>
     */
    public static function phpUploadErrors(): array
    {
        return [
            'over the server limit'        => [UPLOAD_ERR_INI_SIZE, 'larger than this server accepts'],
            'over the form limit'          => [UPLOAD_ERR_FORM_SIZE, 'larger than this server accepts'],
            'cut off part-way'             => [UPLOAD_ERR_PARTIAL, "didn't finish uploading"],
            'no temporary folder'          => [UPLOAD_ERR_NO_TMP_DIR, "didn't upload properly"],
            'could not be written'         => [UPLOAD_ERR_CANT_WRITE, "didn't upload properly"],
        ];
    }

    // ------------------------------------------------------------------ storing and removing

    public function testAValidatedNoteIsStoredUnderAGeneratedNameAndCanBeDeleted(): void
    {
        $uploader = $this->uploader(verifyWithFfprobe: false);
        $upload   = AudioFixtures::upload('chrome-recording.webm', 'voice-note.webm');

        $this->assertTrue($uploader->validate($upload, 6)['valid']);

        $path = $uploader->store($upload);

        $this->assertMatchesRegularExpression('#^' . self::STORE_SUBPATH . '/\d+_[a-f0-9]+\.webm$#', $path, 'The visitor\'s own file name must never reach disk.');
        $this->assertFileExists(WRITEPATH . $path);

        $this->assertTrue($uploader->delete($path));
        $this->assertFileDoesNotExist(WRITEPATH . $path);
        $this->assertFalse($uploader->delete($path), 'Deleting something already gone is a quiet false, not an error.');
    }

    public function testAFixtureIsNeverConsumedByStoringIt(): void
    {
        $uploader = $this->uploader(verifyWithFfprobe: false);

        $uploader->store(AudioFixtures::upload('chrome-recording.webm', 'voice-note.webm'));

        $this->assertFileExists(AudioFixtures::path('chrome-recording.webm'));
    }

    public function testANoteThatHasAlreadyBeenStoredIsNotAcceptedTwice(): void
    {
        $uploader = $this->uploader(verifyWithFfprobe: false);
        $upload   = AudioFixtures::upload('chrome-recording.webm', 'voice-note.webm');

        $uploader->store($upload);

        $result = $uploader->validate($upload, 6);

        $this->assertFalse($result['valid']);
        $this->assertSame('This file has already been processed.', $result['message']);
    }
}
